/// <reference lib="dom" />
/// <reference lib="dom.iterable" />
/// <reference lib="es2023" />

import {
  loadFont as loadInter,
  loadFont as loadSans,
} from "@remotion/google-fonts/Inter";
import {
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  type ReactNode,
  useContext,
  useEffect,
  useId,
  useState,
} from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  Interactive,
  type InteractivitySchema,
  Sequence,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadInstrumentSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadOutfit } from "@remotion/google-fonts/Outfit";
import { loadFont as loadSpaceGrotesk } from "@remotion/google-fonts/SpaceGrotesk";

/**
 * The type faces a scene's `fontFamily` may name.
 *
 * ## Why an allowlist and not a free string
 *
 * Every component in this registry loads its face through
 * `@remotion/google-fonts` rather than a CSS variable, for the reason spelled
 * out at the top of each one: a Remotion bundle has none of the app's CSS, so
 * `var(--font-…)` gets you the right face in the Player and a **fallback in the
 * mp4**. A bare family name handed to a component has exactly the same problem
 * — the browser preview finds it, the render does not, and the bug is invisible
 * until someone plays the file.
 *
 * So a name only counts as a font here if this module has loaded it. Values map
 * label → the real CSS family string `loadFont` returns, which is not always the
 * label ("Instrument Serif", not "InstrumentSerif").
 *
 * ## A raw stack still works
 *
 * `resolveFont` passes anything it does not recognise straight through, so a
 * caller who has loaded their own face — a brand font, a local `@font-face` —
 * names it directly and gets it. The allowlist is the safe path, not the only one.
 *
 * ponytail: all six load at module scope, so a render fetches six latin subsets
 * whether or not the video uses them. Move to a lazy per-family `loadFont()` if
 * bundle time ever shows up in a render trace.
 */
const FONTS: Record<string, string> = {
  Inter: loadInter("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Geist: loadGeist("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  "Space Grotesk": loadSpaceGrotesk("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Outfit: loadOutfit("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Montserrat: loadMontserrat("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  // 400 is the only weight this family ships. Asking for 600 throws.
  "Instrument Serif": loadInstrumentSerif("normal", {
    weights: ["400"],
    subsets: ["latin"],
  }).fontFamily,
};

/**
 * What a select control offers. `DEFAULT_FONT` first: a scene's own face is a
 * design decision, so the knob has to have an "off", and it has to be the
 * value it ships at.
 */
const DEFAULT_FONT = "Default";

/**
 * Label → loaded CSS family. Anything unrecognised passes through unchanged, so
 * a caller's own stack is never swallowed. `undefined` in, `undefined` out —
 * that is the signal for "keep the component's own face".
 */
const resolveFont = (name?: string): string | undefined =>
  !name || name === DEFAULT_FONT ? undefined : (FONTS[name] ?? name);

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#1d6bff", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#1d6bff",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#1d6bff", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#1d6bff",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

/**
 * A sentence that finishes itself over and over: "Create your own ☑ Intros",
 * then Demos, Launches, Changelogs, Tutorials, "And more" — each word rolling
 * up out of a slot beside a ticked checkbox — then the line steps back a little
 * and rests.
 *
 * ## Everything here was measured off a recording, frame by frame
 *
 * The numbers below are not taste. They were recovered from a 2.17 second,
 * 718 × 394 screen capture (65 frames) by fitting renders of this scene to it
 * in BT.709 Y′CbCr, through a model of the capture's own resampling kernel:
 *
 *   - the recording is a 30fps video captured at a jittery ~30Hz: its
 *     timestamps wander ±8ms, but snapped to a 30fps grid every capture frame
 *     is exactly one source frame — none doubled, none dropped. Fitted on that
 *     clock instead of the stamps, every curve below came out clean.
 *   - the two words in the slot move as ONE strip — the gap between the word
 *     leaving and the word arriving is constant to 0.2px on every frame of a
 *     roll — so it is one curve, not an ease-in exit and an ease-out entrance.
 *     It is `cubic-bezier(0.65, 0, 0.35, 1)` over exactly 0.5s, a roll every
 *     20 frames: 0.076px RMS across both rolls. The runner-up, quart in-out,
 *     is 0.10; the CSS `ease-in-out` is 0.69.
 *   - the strip does not travel the same distance every time: 44.19px, then
 *     42.27px. Both are shipped, in `TRAVEL`, and cycle.
 *
 * ## The type is Inter 3, and that was measured too
 *
 * Fingerprinted on the five words the recording shows, at matched width:
 * Inter 500 is 0.45px RMS from the reference, the next face (Be Vietnam Pro)
 * 0.48, Helvetica 0.50, Geist 0.61. SF Pro, fitted outline against outline,
 * is 37% worse than Inter. And it is Inter *3*: the same fit against Inter
 * 3.19 is 12% closer across all four lines than against the Inter 4 Google
 * serves today, and a third closer on the lead-in alone. So 3.19 is loaded
 * (OFL, from fontsource), with Google's Inter behind it as the fallback.
 *
 * ## The checkbox sits still, and everything is laid out from it
 *
 * The lead-in is right-aligned to the box and the word left-aligned from it, so
 * the sentence survives new copy: the box never moves, only the words around it
 * change width — which is also what the reference does when "Docs" becomes
 * "And more".
 */

const { fontFamily: SANS } = loadSans("normal", {
  weights: ["500"],
  subsets: ["latin"],
});

const FACE = "Check Cycle Inter";
const FACE_URL =
  "https://cdn.jsdelivr.net/npm/@fontsource/inter@4.5.15/files/inter-latin-500-normal.woff2";
let faceLoad: Promise<unknown> | null = null;
function loadFace(): Promise<unknown> {
  if (faceLoad) return faceLoad;
  if (typeof FontFace === "undefined") {
    faceLoad = Promise.resolve();
    return faceLoad;
  }
  const face = new FontFace(FACE, `url(${FACE_URL}) format("woff2")`, {
    weight: "500",
  });
  document.fonts.add(face);
  // A face that fails to load leaves Google's Inter to paint — close, not exact.
  faceLoad = face.load().catch(() => undefined);
  return faceLoad;
}

/* ─────────────────────────────────────────────────────────────────────────
   The scene, in the reference's own 718 × 394 pixels
   ───────────────────────────────────────────────────────────────────────── */

const REF_W = 718;
const REF_H = 394;

/** Type size of both halves of the sentence. Fitted per line: 21.62–21.97. */
const SIZE = 21.78;
/** Where the lead-in's advance ends — it is right-aligned to this x. */
const LEAD_END = 340.04;
/** The lead-in's baseline. */
const LEAD_BASE = 203.01;
/** Where the word's advance starts. */
const WORD_X = 379.1;
/** The word's baseline: 1.5px below the lead-in's, on every word shown. */
const WORD_BASE = 204.97;

/** The checkbox, as x, y, width, height, corner radius. */
const BOX = { x: 345.11, y: 183.71, w: 27.03, h: 27.59, r: 6.53 };
/** The tick, as three points in the box's own coordinates, and its stroke. */
const TICK: readonly (readonly [number, number])[] = [
  [5.468, 13.785],
  [11.827, 18.695],
  [20.72, 8.888],
];
const TICK_W = 2.72;

/**
 * The slot the words roll through: a hard clip, top and bottom. Fitted as a
 * feathered mask across eight frames with both words visible — the feathers
 * came back at 2.1px and 1.0px, which is the capture's blur, not a fade.
 */
const SLOT = [171.37, 223.62] as const;

/** How far the strip travels on each roll, in turn. */
const TRAVEL = [44.19, 42.27] as const;
/** When the first roll starts, how often a roll comes, and how long it takes. */
const ROLL_AT = 0.0324;
const ROLL_EVERY = 0.667;
const ROLL_FOR = 0.5;
/** The roll's curve: the in-out cubic. */
const ROLL_EASE = Easing.bezier(0.65, 0, 0.35, 1);

/** How long the last word holds after its roll starts, before the step back. */
const HOLD = 1.004;

/**
 * The step back: the line shrinks about the frame's centre to `ZOOM_TO` and
 * rests there. The recording falls all the way to nothing; this keeps only the
 * start of that — a settle, not an exit.
 */
const PIVOT = [359.14, 197.52] as const;
const ZOOM_TO = 0.8;
const ZOOM_FOR = 0.6;
const ZOOM_EASE = Easing.bezier(0.65, 0, 0.35, 1);

const unit = (v: number) => Math.min(1, Math.max(0, v));

/** Strip travel at `now` seconds, for a list of `n` words. */
function stripAt(now: number, n: number): number {
  let s = 0;
  for (let k = 0; k < n - 1; k++) {
    const p = unit((now - (ROLL_AT + k * ROLL_EVERY)) / ROLL_FOR);
    s += (TRAVEL[k % TRAVEL.length] ?? 0) * ROLL_EASE(p);
  }
  return s;
}

/** Where word `k` rests on the strip. */
function restOf(k: number): number {
  let c = 0;
  for (let j = 0; j < k; j++) c += TRAVEL[j % TRAVEL.length] ?? 0;
  return c;
}

/** When the step back starts, for `n` words. */
function zoomStart(n: number): number {
  return ROLL_AT + Math.max(0, n - 2) * ROLL_EVERY + HOLD;
}

/** Camera scale at `now`: 1, easing down to `ZOOM_TO`. */
function zoomAt(now: number, n: number): number {
  return 1 - (1 - ZOOM_TO) * ZOOM_EASE(unit((now - zoomStart(n)) / ZOOM_FOR));
}

/**
 * A line of type that can sit — and move — a fraction of a pixel.
 *
 * Chrome rounds a glyph run's baseline to a whole device pixel, in HTML and
 * SVG alike, with or without `will-change`. On the roll's slow lift-off that
 * is measured, not theoretical: the word held still for four frames and then
 * jumped a pixel, three times, before it started to move at all.
 *
 * So the line is painted twice, one device pixel apart, both copies placed ON
 * a whole pixel so there is nothing left to round, and cross-faded by the
 * fraction in between. `plus-lighter` adds the two copies' coverage instead of
 * stacking one over the other, so the blend is exactly linear: a baseline at
 * 0.25 of a pixel reads as 0.25, and the ink's centroid moves in steps of
 * 1/8 px when it is asked to (measured). That is the resample a video of this
 * line would have — which is what the reference is.
 */
function Line({
  x,
  y,
  dev,
  anchor,
  style,
  children,
}: {
  x: number;
  y: number;
  dev: { a: number; b: number };
  anchor?: "end";
  style: CSSProperties;
  children: string;
}) {
  const d = dev.a * y + dev.b;
  const lo = Math.floor(d);
  const f = d - lo;
  // A thousandth of a pixel inside the row, so the rounding has nowhere to go.
  const at = (row: number) => (row + 1e-3 - dev.b) / dev.a;
  return (
    <g style={{ isolation: "isolate" }}>
      {[
        [lo, 1 - f],
        [lo + 1, f],
      ].map(([row, w]) => (
        <text
          key={row}
          x={x}
          y={at(row ?? 0)}
          textAnchor={anchor}
          style={{ ...style, opacity: w, mixBlendMode: "plus-lighter" }}
        >
          {children}
        </text>
      ))}
    </g>
  );
}

export interface CheckCycleProps {
  /** The part of the sentence that never changes. */
  headline?: string;
  /** The words that finish it, in order, comma separated. */
  words?: string;
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
  fontFamily?: string;
}

function CheckCycleScene({
  headline = "Create your own",
  words = "Intros, Demos, Launches, Changelogs, Tutorials, And more",
  theme,
  mode = "light",
  fontFamily = "Default",
}: CheckCycleProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const t = useKitTheme(theme, mode);
  const face = resolveFont(fontFamily) ?? `"${FACE}", ${SANS}`;
  const [handle] = useState(() => delayRender("check-cycle: loading Inter 3"));
  useEffect(() => {
    loadFace().then(() => continueRender(handle));
  }, [handle]);
  const id = useId().replace(/:/g, "");

  const list = words
    .split(",")
    .map((w) => w.trim())
    .filter(Boolean);
  const n = Math.max(1, list.length);
  const now = frame / fps;

  /**
   * One reference pixel, and the offset that centres the layout. Scaled to
   * whichever side is tighter, so a render at the reference's dimensions *is*
   * the reference's dimensions and nothing resamples mid-comparison.
   */
  const u = Math.min(width / REF_W, height / REF_H);
  const s = stripAt(now, n);
  const z = zoomAt(now, n);

  const type = {
    fontFamily: face,
    fontWeight: 500,
    fontSize: SIZE,
    fill: t.foreground,
    // Unhinted outlines, so the sub-pixel `Line` blend moves the shape it
    // drew rather than a re-hinted one.
    textRendering: "geometricPrecision",
  } as const;

  const top = (height - REF_H * u) / 2;
  // A Remotion render's `scale` is the page's devicePixelRatio.
  const dpr = typeof window === "undefined" ? 1 : window.devicePixelRatio || 1;
  // A baseline, y in scene units, lands on device row a·y + b.
  const [x0, y0] = PIVOT;
  const dev = { a: dpr * u * z, b: dpr * (top + u * y0 * (1 - z)) };

  return (
    <AbsoluteFill
      showInTimeline={false}
      style={{ backgroundColor: t.background }}
    >
      <svg
        width={REF_W * u}
        height={REF_H * u}
        viewBox={`0 0 ${REF_W} ${REF_H}`}
        style={{
          position: "absolute",
          left: (width - REF_W * u) / 2,
          top: (height - REF_H * u) / 2,
          overflow: "visible",
        }}
      >
        <defs>
          <clipPath id={`${id}-slot`}>
            <rect x={0} y={SLOT[0]} width={REF_W} height={SLOT[1] - SLOT[0]} />
          </clipPath>
        </defs>

        <g
          transform={`translate(${x0} ${y0}) scale(${z}) translate(${-x0} ${-y0})`}
        >
          <Line x={LEAD_END} y={LEAD_BASE} dev={dev} anchor="end" style={type}>
            {headline}
          </Line>

          <rect
            x={BOX.x}
            y={BOX.y}
            width={BOX.w}
            height={BOX.h}
            rx={BOX.r}
            fill={t.primary}
          />
          <polyline
            points={TICK.map(([a, b]) => `${BOX.x + a},${BOX.y + b}`).join(" ")}
            fill="none"
            stroke={t.primaryForeground}
            strokeWidth={TICK_W}
            strokeLinecap="round"
            strokeLinejoin="round"
          />

          <g clipPath={`url(#${id}-slot)`}>
            {list.map((word, k) => {
              const y = WORD_BASE + restOf(k) - s;
              // Off the slot entirely: nothing to paint.
              if (Math.abs(y - WORD_BASE) > SLOT[1] - SLOT[0] + SIZE)
                return null;
              return (
                <Line
                  key={`${k}-${word}`}
                  x={WORD_X}
                  y={y}
                  dev={dev}
                  style={type}
                >
                  {word}
                </Line>
              );
            })}
          </g>
        </g>
      </svg>
    </AbsoluteFill>
  );
}

/* ─────────────────────────────────────────────────────────────────────────
   Remotion Studio
   ───────────────────────────────────────────────────────────────────────── */

type CheckCycleElementProps = Omit<
  ComponentProps<typeof CheckCycleScene>,
  | "from"
  | "durationInFrames"
  | "trimBefore"
  | "playbackRate"
  | "loop"
  | "freeze"
  | "hidden"
  | "name"
  | "showInTimeline"
  | "cropLeft"
  | "cropRight"
  | "cropTop"
  | "cropBottom"
  | "premountFor"
  | "postmountFor"
  | "styleWhilePremounted"
  | "styleWhilePostmounted"
  | "controls"
> & {
  readonly style?: CSSProperties;
};

/** What a prop falls back to when Studio does not pass it, reset included. */
const CheckCycleDefaults = {
  headline: "Create your own",
  words: "Intros, Demos, Launches, Changelogs, Tutorials, And more",
  mode: "light",
} satisfies Partial<CheckCycleElementProps>;

/** The Inspector's controls. Timing, transform, crop and premount come with `wrapInSequence`. */
const CheckCycleSchema = {
  headline: {
    type: "text-content",
    default: "Create your own",
    description: "Lead-in",
  },
  words: {
    type: "text-content",
    default: "Intros, Demos, Launches, Changelogs, Tutorials, And more",
    description: "Words (comma separated)",
  },
  mode: {
    type: "enum",
    default: "light",
    description: "Theme",
    variants: { light: {}, dark: {} },
  },
  fontFamily: { type: "font-family", default: undefined, description: "Font" },
} as const satisfies InteractivitySchema;

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function CheckCycleFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

const CheckCycleInner = forwardRef<HTMLDivElement, CheckCycleElementProps>(
  ({ style, ...props }, ref) => {
    // The layer's length, from the Sequence `wrapInSequence` puts around this.
    const { durationInFrames } = useVideoConfig();
    const rest = { ...CheckCycleDefaults, ...props };
    // The scene measures its copy once, on mount. An Inspector edit changes the
    // props without remounting it, so the key does.
    const key = JSON.stringify(props, (k, v) =>
      k === "children" ? undefined : v,
    );

    // width/height are what useVideoConfig() reports inside this Sequence, so
    // the scene lays itself out in its stage rather than the whole composition.
    // It is not a layer of its own: the one Studio shows is the wrapper's.
    return (
      <Sequence
        layout="none"
        showInTimeline={false}
        durationInFrames={durationInFrames}
        width={1280}
        height={720}
      >
        <div
          ref={ref}
          style={{
            position: "relative",
            width: 1280,
            height: 720,
            overflow: "hidden",
            color: "black",
            fontFamily: "initial",
            fontSize: 16,
            fontStyle: "normal",
            fontVariant: "normal",
            fontWeight: 400,
            fontStretch: "normal",
            fontKerning: "auto",
            fontFeatureSettings: "normal",
            fontVariationSettings: "normal",
            lineHeight: "normal",
            letterSpacing: "normal",
            wordSpacing: "normal",
            textAlign: "start",
            textIndent: 0,
            textTransform: "none",
            textShadow: "none",
            textRendering: "auto",
            whiteSpace: "normal",
            wordBreak: "normal",
            overflowWrap: "normal",
            hyphens: "manual",
            direction: "ltr",
            visibility: "visible",
            ...style,
          }}
        >
          <CheckCycleFade>
            <CheckCycleScene key={key} {...rest} />
